/* ============================================================
 * 液态玻璃预设 v5 —— 调用「初始」宿主内建引擎（v1.5.0 玻璃游乐场移植版）
 * ============================================================
 * 架构（v1.5.0 定稿）：引擎代码内建于宿主（WebGL 光学管线 + rAF 实时
 * 渲染），本预设只做两件事：
 *   ① 经 chushi.settings.define 向设置面板贡献游乐场同款调节项（热调即生效）；
 *   ② 经 chushi.glass.enable/patch 调用引擎（配置逐字段白名单夹紧）。
 * 物理模型/参数体系移植自 liquid-glass-webgl（玻璃游乐场）
 *   https://github.com/martin65536/liquid-glass-webgl （作者 martin65536，Apache-2.0）
 * 原型：Kyant0/AndroidLiquidGlass（作者 Kyant0，Apache-2.0）
 * ============================================================ */

chushi.settings.define({
  title: "液态玻璃 · 玻璃游乐场",
  controls: [
    { type: "slider", key: "refractionHeight", label: "折射高度", min: 0, max: 48, step: 1, def: 24, unit: "px" },
    { type: "slider", key: "refractionAmount", label: "折射强度", min: 0, max: 48, step: 1, def: 24, unit: "px" },
    { type: "slider", key: "blur", label: "模糊半径", min: 0, max: 32, step: 1, def: 8, unit: "px" },
    { type: "slider", key: "chromaticPct", label: "色散强度", min: 0, max: 100, step: 5, def: 0, unit: "%" },
    { type: "slider", key: "saturation", label: "饱和度", min: 100, max: 260, step: 5, def: 150, unit: "%" },
    { type: "slider", key: "brightness", label: "透亮", min: 85, max: 115, step: 1, def: 100, unit: "%" },
    { type: "toggle", key: "highlight", label: "边缘高光", def: true },
    {
      type: "select",
      key: "coverage",
      label: "覆盖范围",
      def: "full",
      options: [
        { value: "full", label: "全部玻璃面" },
        { value: "core", label: "基础四区" },
      ],
    },
  ],
});

/* 启用：读持久化设置（宿主已按 schema 校验夹紧）整组传入引擎 */
function toEngine(v) {
  var cfg = {};
  for (var k in v) cfg[k] = v[k];
  /* 色散滑杆以百分比输入，引擎语义为 0..1 */
  if (typeof cfg.chromaticPct === "number") {
    cfg.chromatic = cfg.chromaticPct / 100;
    delete cfg.chromaticPct;
  }
  return cfg;
}

var v = await chushi.settings.get();
var first = await chushi.glass.enable(toEngine(v));
if (first && first.ok === false) {
  chushi.notify({ title: "液态玻璃", description: first.message || "引擎启用失败" });
}

/* 设置面板热调：整组值直接 patch 引擎（引擎侧逐字段夹紧） */
chushi.settings.onChange(function (x) {
  chushi.glass.patch(toEngine(x));
});
